insert into public.packaging_pricing_matrix_rows (
  organization_id, template_id, supply_form, construction_key, client_product_id,
  q1_rate_per_frame, q2_rate_per_frame, q3_rate_per_frame, q4_rate_per_frame, q5_rate_per_frame,
  source_worksheet, source_row_number, source_reference, is_active, metadata
)
select
  'b97913cb-3b95-4247-8ced-ffdc0d392d2a'::uuid,
  t.id,
  s.supply_form, s.construction_key, s.client_product_id,
  s.q1_rate_per_frame, s.q2_rate_per_frame, s.q3_rate_per_frame, s.q4_rate_per_frame, s.q5_rate_per_frame,
  s.source_worksheet, s.source_row_number, s.source_reference, true, s.metadata
from source_rows s
join public.packaging_pricing_templates t
  on t.organization_id = 'b97913cb-3b95-4247-8ced-ffdc0d392d2a'::uuid
 and t.slug = s.template_slug
 and t.calculation_version = 4
on conflict (organization_id, template_id, supply_form, client_product_id) do update set
  construction_key = excluded.construction_key,
  q1_rate_per_frame = excluded.q1_rate_per_frame,
  q2_rate_per_frame = excluded.q2_rate_per_frame,
  q3_rate_per_frame = excluded.q3_rate_per_frame,
  q4_rate_per_frame = excluded.q4_rate_per_frame,
  q5_rate_per_frame = excluded.q5_rate_per_frame,
  source_worksheet = excluded.source_worksheet,
  source_row_number = excluded.source_row_number,
  source_reference = excluded.source_reference,
  is_active = true,
  metadata = excluded.metadata,
  updated_at = now();

-- Hard gate: the migration must contain the complete workbook source, never a partial matrix.
do $$
declare
  v_center integer;
  v_roll integer;
  v_pouch integer;
begin
  select count(*) into v_center
  from public.packaging_pricing_matrix_rows r
  join public.packaging_pricing_templates t on t.id=r.template_id
  where r.organization_id='b97913cb-3b95-4247-8ced-ffdc0d392d2a'::uuid
    and t.slug='stark-center-seal-matrix-v4' and r.supply_form='center_seal' and r.is_active;

  select count(*) into v_roll
  from public.packaging_pricing_matrix_rows r
  join public.packaging_pricing_templates t on t.id=r.template_id
  where r.organization_id='b97913cb-3b95-4247-8ced-ffdc0d392d2a'::uuid
    and t.slug='stark-3ss-roll-matrix-v4' and r.supply_form='three_side_seal_roll' and r.is_active;

  select count(*) into v_pouch
  from public.packaging_pricing_matrix_rows r
  join public.packaging_pricing_templates t on t.id=r.template_id
  where r.organization_id='b97913cb-3b95-4247-8ced-ffdc0d392d2a'::uuid
    and t.slug='stark-3ss-pouch-matrix-v4' and r.supply_form='three_side_seal_pouch' and r.is_active;

  if v_center <> 96 or v_roll <> 48 or v_pouch <> 48 then
    raise exception 'Stark matrix import incomplete: center %, 3SS roll %, 3SS pouch %', v_center, v_roll, v_pouch;
  end if;
end $$;

commit;
